definition.script:
pipeline {
    agent any
    tools {
    maven 'maven' // Adjust to match the Maven version configured in Jenkins
}
    environment {
        // Define environment variables to store credentials and repo info
        GIT_CREDENTIALS = credentials('git_visionaryops')
        GIT_REPO_URL = 'github.com/NOUR-BEN-ALI/MyApp-PFE.git' 
        GIT_BRANCH = 'tempo'
        REPO_DIR = 'MyApp-PFE'
        // Sonar credential
        //SONAR_CREDENTIALS = credentials('sonarqube')
        //SONAR_HOST_URL = 'http://192.168.33.10:9000'
        registry = "docker.io" 
        registryCredential = 'docker_visionaryops' 
        dockerImage = 'nourbenali/visionaryops-microservice11'
        // dockerImages = [
        //     'nourbenali/visionaryops-microservice11',
        //     'nourbenali/visionaryops-microservice22',
        //     'nourbenali/visionaryops-microservice33'
        // ]
    }

    stages {
        stage('Clone my Branch from Git') {
            steps {
                script {
                    if (fileExists(REPO_DIR)) {
                        dir(REPO_DIR) {
                            sh 'git pull'
                        }
                    } else {
                        sh "git clone --branch ${env.GIT_BRANCH} https://NOUR-BEN-ALI:${env.GIT_CREDENTIALS}@${env.GIT_REPO_URL} ${REPO_DIR}"
                    }
                }
            }
        }
        stage('Clean and compile with Maven') {
            steps {
                dir(REPO_DIR) {
                    sh 'mvn clean install -DskipTests'
                }
            }
        }

        //         stage('Junit/Mockito') {
        //     steps {
        //         dir(REPO_DIR) {
        //             sh "mvn test "
        //         }
        //     }
        // }    

        // stage('SonarQube Analysis') {
        //     steps {
        //         dir(REPO_DIR) {
        //             withCredentials([usernamePassword(credentialsId: 'sonarqube', usernameVariable: 'SONAR_USER', passwordVariable: 'SONAR_PASSWORD')]) {
        //                 sh "mvn clean verify sonar:sonar -Dsonar.login=\$SONAR_USER -Dsonar.password=\$SONAR_PASSWORD -Dsonar.host.url=${SONAR_HOST_URL}"
        //             }
        //         }
        //     }
        // }

        // stage('Nexus Deployment') {
        //     steps {
        //         dir(REPO_DIR) {
        //             sh "mvn deploy -DskipTests=true "
        //         }
        //     }
        // }    
// stage('Building  image') { 

//             steps { 
// dir(REPO_DIR){
//                 script { 

//                     dockerImage = docker.build registry + ":$BUILD_NUMBER" 

//                 }
// }

//             } 

//         }

//         stage('Deploy  image') { 

//             steps {
//                 dir(REPO_DIR){

//                 script { 

//                     docker.withRegistry( '', registryCredential ) { 

//                         dockerImage.push() 

//                     }

//                 } 
//                 }

//             }

//         } 

//         stage('Docker Compose Up') {
//             steps {
//                 script {
//                     dir(REPO_DIR) {
//                         // Replace 'docker-compose.yml' with your actual Docker Compose file
//                         sh "docker compose up -d"
//                     }
//                 }
