stage('Build Docker Images') {
            steps {
                script {
                    def images = [
                        'nourbenali/visionaryops-microservice11',
                        'nourbenali/visionaryops-microservice22',
                        'nourbenali/visionaryops-microservice33'
                    ]

                    images.each { image ->
                        dir(REPO_DIR) {
                            def imageTag = "${image}:${env.BUILD_NUMBER}"
                            docker.build(imageTag, "-f ${image}/Dockerfile .")
                            env."${image.replace('/', '_')}_IMAGE" = imageTag
                        }
                    }
                }
            }
        }

        stage('Push Docker Images') {
            steps {
                script {
                    def images = [
                        'nourbenali/visionaryops-microservice11',
                        'nourbenali/visionaryops-microservice22',
                        'nourbenali/visionaryops-microservice33'
                    ]

                    images.each { image ->
                        def imageTag = env."${image.replace('/', '_')}_IMAGE"
                        docker.withRegistry('', registryCredential) {
                            docker.image(imageTag).push()
                        }
                    }
                }
            }
        }

        stage('Docker Compose Up') {
            steps {
                dir(REPO_DIR) {
                    // Replace 'docker-compose.yml' with your actual Docker Compose file
                    sh "docker-compose up -d"
                }
            }
        }

        // stage('Prometheus & Grafana ') {
